if(state.resource && !resourceData[state.resource])state.resource=''
function getResource(id) { return resourceData[id] }
function resourceCard(id, compact = false) {
  const r = getResource(id)
  return `<button data-resource="${id}" id="resource-${id}" class="resource-card ${state.resource === id ? 'selected' : ''} ${['provider','storage','vector'].includes(id) ? 'external' : ''}"><div class="row between"><span class="kind-icon">${icon(r.icon)}</span>${badge(r.status,r.tone)}</div><div><h3>${escapeHtml(r.name)}</h3><p class="small muted" style="margin-top:5px">${escapeHtml(compact ? r.kind : r.sub)}</p></div>${r.issue && !compact ? `<div class="card-warning">${icon(r.tone === 'error' ? 'error' : 'warning')}${escapeHtml(r.issue[0])}</div>` : ''}<div class="card-line"><span>${['provider','storage','vector'].includes(id) ? 'External / Customer integration' : id === 'staging' || id === 'previewapp' ? 'Customer staging' : 'Production'}</span>${icon('chevron')}</div></button>`
}
function header(title, desc, actions = '', meta = '') {
  return `<div class="page-head"><div>${meta ? `<div class="head-meta">${meta}</div>` : ''}<h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`
}
function facts(entries) { return `<dl class="facts">${entries.map(([k,v])=>`<div><dt>${escapeHtml(k)}</dt><dd>${escapeHtml(v)}</dd></div>`).join('')}</dl>` }
function related(ids) { return ids.map(id=>{const r=getResource(id);return `<button class="related" data-resource="${id}">${icon(r.icon)}<span class="grow">${escapeHtml(r.name)}</span><span class="right">${icon('chevron')}</span></button>`}).join('') }
function timeline(compact = false) {
  const events = [
    ['warn','warning','Stock connection needs attention','Vehicle inventory / Production','09:42','provider'],
    ['good','check','Production verification passed','Northfield assistant / Release 1.6.0','09:41','runtime'],
    ['','support','Visitor requested a human','Northfield AI / Human pending','09:39','conversation'],
    ['good','file','Policy indexing completed','3 documents / Customer-owned storage','09:25','documents'],
    ['','apps','Engage app assigned to production','Northfield AI / Installation retained','09:22','app'],
  ]
  return `<div class="timeline">${events.slice(0,compact?3:5).map(([tone,i,t,sub,time,id])=>`<div class="timeline-row"><span class="timeline-icon ${tone}">${icon(i)}</span><div class="grow"><button class="btn ghost" style="padding:0;min-height:0;font-weight:500;white-space:normal;text-align:left" data-resource="${id}">${t}</button><p>${sub}</p></div><span class="time">${time}</span></div>`).join('')}</div>`
}
function table(headers, rows) { return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>` }
function resourceRow(id, values) {
  const r=getResource(id)
  return `<tr data-resource="${id}" class="${state.resource===id?'selected':''}"><td><div class="table-resource">${icon(r.icon)}<div><span class="table-name">${escapeHtml(r.name)}</span><span class="table-sub">${escapeHtml(r.kind)}</span></div></div></td>${values.map(v=>`<td>${v}</td>`).join('')}<td>${icon('chevron')}</td></tr>`
}
function templates() {return `<div class="templates"><button class="template" data-action="create-dealership"><span class="kind-icon">${icon('car')}</span><h2>Dealership experience</h2><p>Vehicle knowledge, approved actions and an Engage workspace, connected to your systems.</p><div class="row wrap">${badge('Conversational','blue')}${badge('Simulator available')}</div><div class="template-footer"><span>Use template</span>${icon('right')}</div></button><button class="template" data-action="create-support"><span class="kind-icon">${icon('support')}</span><h2>Knowledge assistant</h2><p>Answers grounded in your approved documents, with optional human handover.</p><div class="row wrap">${badge('Conversational','blue')}${badge('Customer storage')}</div><div class="template-footer"><span>Use template</span>${icon('right')}</div></button></div>`}
function setupSteps(step = 0) {return `<div class="setup-steps">${['Choose template','Connect your data','Review & deploy'].map((t,i)=>`<div class="setup-step ${i===step?'active':''}"><span class="step-dot">${i<step?icon('check'):i+1}</span>${t}</div>`).join('')}</div>`}
function firstHome() {
  return `<div class="blank-intro"><div class="welcome-line">NORTHFIELD MOTOR HOUSE</div><h1>What would you like to build?</h1><p class="muted" style="margin-top:12px;font-size:13px">Start with a template. Connect your systems. Try your AI in customer staging.</p>${setupSteps()}${templates()}<div class="floating-help">${icon('lock')} Your inventory and business systems remain yours.</div></div>`
}
function graph() {
  const staging = state.environment === 'staging'
  return `<div class="canvas"><div class="canvas-caption"><span class="row gap6">${icon('deployments')} Northfield assistant ${badge(staging?'Customer staging':'Production',staging?'blue':'good')}</span><span class="muted">Release 1.6.0 / Verified</span></div><div class="canvas-inner"><div class="graph"><div><div class="graph-label">Your connected systems</div><div class="graph-column">${resourceCard('provider',true)}${resourceCard('storage',true)}</div></div><div class="connector">${icon('right')}</div><div><div class="graph-label">AI deployment</div><div class="graph-column">${resourceCard(staging?'staging':'runtime',true)}${resourceCard('documents',true)}</div></div><div class="connector">${icon('right')}</div><div><div class="graph-label">User experience</div><div class="graph-column">${resourceCard(staging?'previewapp':'app',true)}${resourceCard('handover',true)}</div></div></div><div class="graph-meta"><span><span class="external-key"></span>External / Customer-owned integration</span><span>Solid outline / AI resource</span></div></div></div>`
}
