function checkRows(rows) {return `<div class="readiness">${rows.map(([i,t,d])=>`<div class="check-row ${i==='warning'?'warn':''}">${icon(i)}<div><strong>${t}</strong><p>${d}</p></div></div>`).join('')}</div>`}
const renderers = {home,deployments,apps,knowledge,connections,support,reviews,behaviors,activity,team}
function inspector() {
  if(!state.resource)return ''
  const r=getResource(state.resource)
  let body=''
  if(state.tab==='activity')body=timeline(true)
  else if(state.tab==='configuration')body=configuration(r)
  else body=`${r.issue?issue(...r.issue):''}<div class="inspect-actions">${button(r.primary[0],r.primary[1],'primary',r.primary[2])}${state.resource==='app'?button('Open app','preview-app','','external'):''}</div>${facts(r.facts)}${state.resource==='brain'?planPreview():''}${state.resource==='conversation'?`<div class="inspect-section"><h3>Latest visitor message</h3><div class="message user">Could someone help me compare the two cars before I book a visit?</div><p class="small muted">AI is paused while the conversation is with a human.</p></div>`:''}${state.resource==='review'?`<div class="review-intent"><h3>Proposed action</h3><p>Create an exception request for the verified order. Approval authorizes this proposal only; it does not expand the action's scope.</p></div>`:''}${r.related.length?`<div class="inspect-section"><h3>Related resources</h3>${related(r.related)}</div>`:''}<details class="advanced"><summary>Advanced details</summary><div class="mono">Resource: ${escapeHtml(r.id)}<br>Observation: 23 Oct 2026, 09:42<br>Fixture only / no live evidence</div></details>`
  return `<aside class="inspector ${state.expanded?'expanded':''}" role="dialog" aria-modal="false" aria-label="${escapeHtml(r.name)} details"><div class="inspect-top"><span>${r.kind}</span><div class="row gap6"><button class="icon-btn" data-action="expand" aria-label="${state.expanded?'Reduce':'Expand'} details" title="${state.expanded?'Reduce':'Expand'} details">${icon('expand')}</button><button class="icon-btn" data-action="close" aria-label="Close details" title="Close details">${icon('close')}</button></div></div><div class="inspect-title"><span class="kind-icon">${icon(r.icon)}</span><h2>${escapeHtml(r.name)}</h2><div class="row wrap">${badge(r.status,r.tone)}<span class="small muted">${escapeHtml(r.sub)}</span></div></div><div class="inspect-tabs">${['overview','configuration','activity'].map(tab=>`<button data-tab="${tab}" class="${state.tab===tab?'active':''}">${tab[0].toUpperCase()+tab.slice(1)}</button>`).join('')}</div><div class="inspect-body">${body}</div><div class="panel-footer">Northfield Motor House / Authorized customer scope</div></aside>`
}
function configuration(r) {
  if(['app','previewapp'].includes(state.resource))return `<div class="form-group"><label class="label" for="app-name">App name</label><input class="field" id="app-name" value="${r.name}"></div><div class="form-group"><label class="label" for="experience-pack">Experience pack</label><select class="field" id="experience-pack"><option>Dealership experience / 1.1.0</option></select></div><div class="form-group"><label class="label" for="app-domain">Custom domain</label><input class="field" id="app-domain" value="ai.northfield.example.com"></div>${issue('DNS verification pending','Your default app address is unaffected.','warn')}<div class="form-group"><label class="label" for="visitor-access">Visitor access</label><select class="field" id="visitor-access"><option>Anonymous + sign-in for protected actions</option><option>Sign-in required</option></select></div><div class="form-group"><label class="label" for="workspace-label">Workspace label</label><input class="field" id="workspace-label" value="Northfield AI"></div><div class="row wrap">${button('Save preview','save-preview','primary')}${button('Installation','installation','','code')}</div>`
  if(['provider','storage','vector'].includes(state.resource))return `${r.issue?issue(...r.issue):''}<div class="form-group"><label class="label" for="connection-target">Target</label><select class="field" id="connection-target"><option>Production / Northfield assistant</option><option>Customer staging / Northfield assistant</option></select></div><div class="form-group"><label class="label" for="binding-profile">Approved binding profile</label><input class="field" id="binding-profile" value="${state.resource==='storage'?'Customer-owned read-only S3':state.resource==='provider'?'Advertiser-scoped stock integration':'Customer-provided vector search'}" readonly></div><div class="form-group"><label class="label" for="replacement-secret">Replacement credential</label><input class="field" type="password" id="replacement-secret" placeholder="Enter a new credential" autocomplete="off"><p class="small muted" style="margin-top:8px">Current credentials are configured and cannot be read back.</p></div>${button('Review change','save-preview','primary')}`
  if(state.resource==='handover')return `<h3>Visitor entry</h3><div class="toggle-line"><span>Allow visitor transfer button</span><button class="switch on" role="switch" aria-checked="true" aria-label="Visitor transfer button" data-action="toggle-local"></button></div><div class="toggle-line"><span>Allow reviewed AI handover action</span><button class="switch on" role="switch" aria-checked="true" aria-label="AI handover action" data-action="toggle-local"></button></div><div class="divider"></div><div class="form-group"><label class="label" for="contact-email">Email</label><select class="field" id="contact-email"><option>Required before transfer</option><option>Optional</option></select></div><div class="form-group"><label class="label" for="contact-name">Name</label><select class="field" id="contact-name"><option>Optional</option><option>Required before transfer</option></select></div><div class="form-group"><label class="label" for="return-policy">Return to AI</label><input class="field" id="return-policy" value="Explicit authorized transition" readonly></div>${button('Save preview','save-preview','primary')}`
  if(['brain','conversational','specialists'].includes(state.resource))return `<h3>Approved profile</h3><p class="small muted" style="margin-top:10px">${r.sub}</p>${facts(r.facts.slice(0,4))}${planPreview()}${issue('Customer permissions must be verified','This design does not expose staff readiness approvals or unrestricted execution.','info')}`
  return `<div class="form-group"><label class="label" for="resource-name">Resource name</label><input class="field" id="resource-name" value="${escapeHtml(r.name)}"></div>${facts(r.facts)}<div class="inspect-actions">${button('Open shared editor','shared-editor','primary','settings')}</div>`
}
function planPreview() {return `<div class="inspect-section"><h3>Execution plan</h3><div class="plan-steps"><div class="plan-step">Receive scoped event<small>Sequential / Validated input</small></div><div class="parallel-steps"><div class="plan-step">Inspect knowledge<small>Parallel worker</small></div><div class="plan-step">Inspect source status<small>Parallel worker</small></div></div><div class="plan-step">Produce typed result<small>Sequential / Approved delivery</small></div></div></div>`}
function modal() {
  if(!state.modal)return ''
  let title='',body='',footer=''
  if(state.modal==='create'){
    title='Create an AI deployment'
    body=`${setupSteps(state.step)}${state.step===0?`<div class="form-group"><label class="label" for="deployment-name">Deployment name</label><input class="field" id="deployment-name" value="Northfield assistant"></div><div class="form-group"><label class="label" for="template-choice">Approved template</label><select class="field" id="template-choice"><option>${state.template==='dealership'?'Dealership experience':'Knowledge assistant'}</option></select></div><div class="form-group"><label class="label" for="setup-target">Initial environment</label><input class="field" id="setup-target" value="Customer staging" readonly></div>`:state.step===1?`${related(['provider','storage'])}<div class="form-group" style="margin-top:20px"><label class="label" for="ai-state">AI-state storage</label><select class="field" id="ai-state"><option>Optional managed AI-state PostgreSQL</option><option>Approved customer-provided AI-state service</option></select></div><p class="small muted">Inventory and business requests stay in your connected systems.</p>`:`${facts([['Template',state.template==='dealership'?'Dealership experience':'Knowledge assistant'],['Environment','Customer staging'],['Stock system','External integration'],['Documents','Customer-owned storage'],['AI state','Optional managed PostgreSQL']])}${issue('Staging only','Production requires its own reviewed bindings and verification.','info')}`}`
    footer=`${button(state.step?'Back':'Cancel',state.step?'step-back':'close-modal')}${button(state.step===2?'Create staging preview':'Continue',state.step===2?'finish-create':'step-next','primary',state.step===2?'deployments':'right')}`
  }else if(state.modal==='promote'){
    title='Review production go-live'
    body=`<div class="promote-columns"><div class="target-box">${badge('Source','blue')}<h3>Customer staging</h3><p class="small muted">Northfield assistant</p><p class="mono" style="margin-top:8px">Version 1.6.0 / Verified</p></div>${icon('right')}<div class="target-box">${badge('Target','good')}<h3>Production</h3><p class="small muted">Same Engage installation</p><p class="mono" style="margin-top:8px">Independent source indexing</p></div></div>${checkRows([['check','Exact source candidate verified','Template and configuration are pinned to the reviewed version.'],['check','Engage assignment preserved','The same app address will use the verified production release.'],['warning','Production stock connection needs attention','Review the target binding before go-live.']])}${issue('Activation is blocked','A failed production prerequisite cannot be skipped from this panel.','warn','resource:provider','Review connection')}`
    footer=`${button('Close','close-modal')}${button('Activate production','blocked-preview','primary','shield','disabled')}`
  }else if(state.modal==='decision'){
    title='Review action proposal'
    body=`${badge('Separate enabled review fixture','blue')}<div class="review-intent"><h2>Refund exception</h2><p>Create an exception request for verified order EXAMPLE-1042. This does not approve a cash transfer or another action.</p></div>${facts([['Task version','3 / Pending'],['Decision scope','Current proposal only'],['Decision owner','Authorized customer reviewer'],['Expires','Today, 17:00']])}<div class="form-group" style="margin-top:20px"><label class="label" for="decision-note">Decision note</label><textarea class="field" id="decision-note" placeholder="Optional note"></textarea></div>`
    footer=`${button('Reject preview','review-rejected','danger')}${button('Approve preview','review-approved','primary','check')}`
  }else{
    title=state.modal==='invite'?'Invite a team member':state.modal==='installation'?'Workspace installation':state.modal==='document'?'Delivery policy.txt':'Preview action'
    body=state.modal==='invite'?`<div class="form-group"><label class="label" for="invite-email">Email</label><input class="field" id="invite-email" type="email" placeholder="colleague@example.com"></div><div class="form-group"><label class="label" for="invite-access">Approved access</label><select class="field" id="invite-access"><option>Existing customer access policy</option></select></div>`:state.modal==='installation'?`<label class="label">Script installation</label><pre class="code">&lt;script src="https://api.example.com/api/public/ai-workspace/install.js"
  data-installation="preview-installation"&gt;&lt;/script&gt;</pre><p class="small muted" style="margin-top:18px">The published installation resolves its authorized deployment assignment.</p>`:state.modal==='document'?`<div class="code">Fictional dealership delivery policy\n\nDelivery is available within 25 miles.\nAllow three working days after payment and vehicle preparation.\nA customer must present photo identification at handover.</div>`:`<p class="muted small">This is a visual preview. No live app, provider, deployment or account is changed.</p>`
    footer=`${button('Close','close-modal')}${state.modal==='invite'?button('Preview invitation','save-preview','primary','mail'):''}`
  }
  return `<div class="modal-scrim"><section class="modal" role="dialog" aria-modal="true" aria-label="${title}"><div class="modal-head"><div><h2>${title}</h2><p class="modal-title-meta">Northfield Motor House</p></div><button class="icon-btn" data-action="close-modal" title="Close dialog" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div><div class="modal-foot">${footer}</div></section></div>`
}
function navigation() {
  const visible=(id)=>id==='reviews'&&state.disabledReview?false:state.stage==='first'?['home','deployments','apps','team'].includes(id):state.stage==='staging'?!['reviews','behaviors'].includes(id):true
  return pages.filter(([id])=>visible(id)).map(([id,label,i])=>`${id==='knowledge'?'<div class="nav-label">Capabilities</div>':''}${id==='activity'?'<div class="nav-label">Workspace</div>':''}<button class="nav-item ${state.page===id?'active':''}" data-page="${id}" ${state.page===id?'aria-current="page"':''}>${icon(i)}${label}${id==='reviews'&&!state.disabledReview?'<span class="count">1</span>':''}${id==='activity'&&state.stage==='operating'?'<span class="count">2</span>':''}</button>`).join('')
}
function render(push = false) {
  if(push){const params=new URLSearchParams({page:state.page,stage:state.stage,environment:state.environment});if(state.resource)params.set('resource',state.resource);history.pushState(null,'',`#${params}`)}
  const page=pages.find(([id])=>id===state.page)
  const advancedHint=['behaviors','support','reviews'].includes(state.page)?'Expanded capability fixtures / scope verification required':'Fictional fixtures / no live API'
  document.querySelector('#root').innerHTML=`<div class="prototype-bar"><span class="prototype-label">DESIGN PREVIEW / 010.45</span><span class="muted">${advancedHint}</span><label style="margin-left:auto"><span class="small" style="margin-right:7px">Layout</span><select id="page-review-select" aria-label="Review page layout">${pages.map(([id,label])=>`<option value="${id}" ${id===state.page?'selected':''}>${label}</option>`).join('')}</select></label><div class="stage-switch" aria-label="Progressive disclosure stage">${[['first','First setup'],['staging','Staging ready'],['operating','Operating']].map(([id,label])=>`<button data-stage="${id}" class="${state.stage===id?'active':''}">${label}</button>`).join('')}</div></div><div class="mobile-scrim ${state.menu?'open':''}" data-action="close-menu"></div><div class="shell"><aside class="sidebar ${state.menu?'open':''}"><div class="brand"><span class="brand-mark">${icon('hub')}</span>LoomAI</div><div class="workspace"><span class="avatar">NM</span><div class="grow"><strong style="font-size:11px">Northfield Motor House</strong><p class="muted" style="font-size:10px">Customer workspace</p></div>${icon('down')}</div><nav aria-label="Customer navigation">${navigation()}</nav><div class="nav-spacer"></div><div class="sidebar-foot"><div class="row"><span class="avatar green">JO</span><div><strong style="font-size:11px;color:#5d6675">Jamie Owner</strong><p style="font-size:10px">Customer administrator</p></div></div></div></aside><div class="main-shell"><header class="topbar"><div class="row grow"><button class="icon-btn mobile-menu" data-action="menu" title="Open navigation" aria-label="Open navigation">${icon('menu')}</button><div class="breadcrumbs"><span>Northfield</span>${icon('chevron')}<strong>${page[1]}</strong>${state.resource?`${icon('chevron')}<span class="truncate">${escapeHtml(getResource(state.resource).name)}</span>`:''}</div></div><div class="row"><span class="top-status small muted">Customer console</span><button class="icon-btn" data-action="go:activity" title="Activity and alerts" aria-label="Activity and alerts">${icon('bell')}</button><span class="avatar green">JO</span></div></header><div class="content-grid ${state.resource?'has-inspector':''}"><main class="page" id="page-main">${renderers[state.page]()}</main>${inspector()}</div></div></div>${modal()}${state.toast?`<div class="toast" role="status">${escapeHtml(state.toast)}</div>`:''}`
}
function openResource(id) { if(!resourceData[id])return;state.resource=id;state.tab='overview';state.modal='';state.expanded=false;render(true) }
function toast(text) {state.toast=text;render();clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>{state.toast='';render()},4200)}
function action(name, element) {
  if(name.startsWith('go:')){state.page=name.slice(3);state.resource='';state.menu=false;state.query='';render(true);return}
  if(name.startsWith('resource:')){openResource(name.slice(9));return}
  if(name==='close'){const id=state.resource;state.resource='';state.expanded=false;render(true);document.querySelector(`#resource-${id}`)?.focus();return}
  if(name==='expand'){state.expanded=!state.expanded;render();return}
  if(name==='menu'||name==='close-menu'){state.menu=name==='menu';render();return}
  if(name==='close-modal'){state.modal='';render();return}
  if(name==='create'||name==='create-dealership'||name==='create-support'){state.modal='create';state.step=0;state.template=name==='create-support'?'support':'dealership';render();return}
  if(name==='step-next'||name==='step-back'){state.step+=name==='step-next'?1:-1;render();return}
  if(name==='finish-create'){state.modal='';state.stage='staging';state.page='deployments';state.environment='staging';state.resource='staging';toast('Staging preview selected. No deployment was created.');return}
  if(name==='promote'||name==='decision'||name==='invite'||name==='installation'){state.modal=name;render();return}
  if(name==='document-preview'){state.modal='document';render();return}
  if(['app-domain','connection-settings','behavior-settings'].includes(name)){state.tab='configuration';render();return}
  if(name==='toggle-review'){state.disabledReview=!state.disabledReview;state.resource='';render();return}
  if(name==='toggle-local'){element.classList.toggle('on');element.setAttribute('aria-checked',String(element.classList.contains('on')));return}
  if(name==='connection-filter'){openResource('provider');return}
  if(name==='alerts-filter'){openResource('provider');return}
  if(name==='review-history'){toast('History layout uses the same scoped review-task inspector. Preview only.');return}
  if(name==='noop')return
  if(name==='review-approved'||name==='review-rejected'){state.modal='';toast('Decision preview only. No action was approved or executed.');return}
  if(name==='open-inbox'){toast('Authorized Inbox entry point. No operator session is opened in this preview.');return}
  if(name==='preview-app'){toast('App link preview. No live customer app is opened.');return}
  if(name==='profiles'){toast('Only entitled, reviewed behaviour profiles would be listed here.');return}
  if(name==='add-source'){toast('Reuse approved live-data or document source setup. No upload or indexing was started.');return}
  if(name==='add-connection'){toast('Approved integration binding picker. No credentials are requested by this preview.');return}
  if(name==='create-app'){toast('The shared Engage configuration editor would open. No installation was created.');return}
  if(name==='refresh-preview'){toast('Preview data retained. No live verification request was sent.');return}
  if(name==='save-preview'){toast('Preview only. No configuration, credential, invitation or live resource was saved.');return}
  toast('Design preview only. This action does not call a live service.')
}
document.addEventListener('click',e=>{
  const stage=e.target.closest('[data-stage]');if(stage){state.stage=stage.dataset.stage;state.resource='';state.modal='';state.environment=state.stage==='operating'?'production':'staging';render(true);return}
  const page=e.target.closest('[data-page]');if(page){action(`go:${page.dataset.page}`);return}
  const env=e.target.closest('[data-env]');if(env){state.environment=env.dataset.env;state.resource='';render(true);return}
  const view=e.target.closest('[data-view]');if(view){state.view=view.dataset.view;render();return}
  const tab=e.target.closest('[data-tab]');if(tab){state.tab=tab.dataset.tab;render();return}
  const resource=e.target.closest('[data-resource]');if(resource){openResource(resource.dataset.resource);return}
  const target=e.target.closest('[data-action]');if(target)action(target.dataset.action,target)
})
document.addEventListener('change',e=>{
  if(e.target.id==='page-review-select'){action(`go:${e.target.value}`)}
  if(e.target.id==='color-theme'){
    themePreference=e.target.value
    try{localStorage.setItem('loomai-customer-preview-theme',themePreference)}catch{}
    applyTheme()
  }
})
document.addEventListener('input',e=>{
  if(e.target.id==='resource-search'){
    state.query=e.target.value
    document.querySelector('#filtered-resources').innerHTML=(state.stage==='staging'?['previewapp']:['app','previewapp']).filter(id=>getResource(id).name.toLowerCase().includes(state.query.toLowerCase())).map(id=>resourceCard(id)).join('')
  }
})
document.addEventListener('keydown',e=>{
  if(e.key==='Escape'){if(state.modal){state.modal='';render()}else if(state.resource){action('close')}else if(state.menu){state.menu=false;render();document.querySelector('[data-action="menu"]')?.focus()}}
})
window.addEventListener('popstate',()=>{const p=new URLSearchParams(location.hash.slice(1));const requestedPage=p.get('page');state.page=pages.some(([id])=>id===requestedPage)?requestedPage:'home';state.stage=['first','staging','operating'].includes(p.get('stage'))?p.get('stage'):'operating';state.environment=p.get('environment')==='staging'?'staging':'production';state.resource=resourceData[p.get('resource')]?p.get('resource'):'';state.tab='overview';state.modal='';render()})
render()
function installThemeControl(){
  const bar=document.querySelector('.prototype-bar')
  if(!bar||bar.querySelector('#color-theme'))return
  const label=document.createElement('label')
  label.className='row gap6'
  label.innerHTML=`<span>Theme</span><select id="color-theme" aria-label="Color theme">${['system','light','dark'].map(mode=>`<option value="${mode}" ${themePreference===mode?'selected':''}>${mode[0].toUpperCase()+mode.slice(1)}</option>`).join('')}</select>`
  bar.insertBefore(label,bar.querySelector('.stage-switch'))
}
new MutationObserver(installThemeControl).observe(document.querySelector('#root'),{childList:true})
installThemeControl()
